    test_cases = [
        (100.0, 9, 900.0, "Boundary: Quantity 9 (No discount)"),
        (100.0, 10, 900.0, "Boundary: Quantity 10 (Start of 10% off)"),
        (100.0, 49, 441.0, "Boundary: Quantity 49 (End of 10% off)"),
        (100.0, 50, 375.0, "Boundary: Quantity 50 (Start of 25% off)")
