	if err != nil || n < 0 {
		fmt.Fprintln(os.Stderr, "Error: argument must be a non-negative integer")
		os.Exit(1)
	}

	for i := 2; i <= n; i++ {
		if isPrime(i) {
			fmt.Println(i)
		}
	}
}
