        (10.0, 49, 441.0, "Boundary: Quantity < 50 (end of 10% off)"),
        (10.0, 50, 375.0, "Boundary: Quantity >= 50 (start of 25% off)"),
    ]

    for price, quantity, expected, description in test_cases:
